const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '一元二次方程求根公式图示' },
      { kind: 'text', payload: '1x² − 4x + 4 = 0' },
      { kind: 'text', payload: 'x = (−b ± √(b² − 4ac)) / (2a)' },
      { kind: 'text', payload: 'b = −4' },
      { kind: 'text', payload: 'c = 4' },
      { kind: 'text', payload: 'a = 1' },
      { kind: 'text', payload: '判别式：Δ = b² − 4ac' },
      { kind: 'text', payload: 'Δ = (−4)² − 4·1·4 = 16 − 16 = 0' },
      { kind: 'text', payload: 'x = (−(−4) ± √0) / (2·1) = (4 ± 0) / 2 = 2' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var paths = [];
    var children = [];
    var dark = '#1f2d3d';
    var purple = '#7c3aed';
    var orange = '#d97706';
    var green = '#16a34a';
    var blue = '#2563eb';

    function addPath(id, commands, fill, strokeWidth) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id, fill: fill };
      if (strokeWidth) {
        node.stroke = { width: strokeWidth };
      }
      children.push(node);
    }

    function addLabel(idx, x, y, hAlign, vAlign, color) {
      children.push({
        type: 'label',
        contentId: metrics[idx].contentId,
        anchor: { x: x, y: y },
        hAlign: hAlign,
        vAlign: vAlign,
        color: color
      });
    }

    function addArrow(x1, y1, x2, y2, color, id) {
      addPath(id + '-shaft', [['M', x1, y1], ['L', x2, y2]], color, 2);
      var dx = x2 - x1;
      var dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len === 0) return;
      var ux = dx / len;
      var uy = dy / len;
      var headLen = 8;
      var headW = 4;
      var bx = x2 - ux * headLen;
      var by = y2 - uy * headLen;
      var px = -uy;
      var py = ux;
      var p1x = bx + px * headW;
      var p1y = by + py * headW;
      var p2x = bx - px * headW;
      var p2y = by - py * headW;
      addPath(id + '-head', [['M', x2, y2], ['L', p1x, p1y], ['L', p2x, p2y], ['Z']], color, 0);
    }

    addLabel(0, w / 2, h * 0.07, 'center', 'middle', dark);
    addLabel(1, w / 2, h * 0.15, 'center', 'middle', dark);
    addLabel(2, w / 2, h * 0.27, 'center', 'middle', dark);

    var r = 4;
    var anchors = [
      { x: w * 0.24, color: orange, labelIdx: 3, labelX: w * 0.22, id: 'dot-b' },
      { x: w * 0.54, color: green, labelIdx: 4, labelX: w * 0.52, id: 'dot-c' },
      { x: w * 0.82, color: blue, labelIdx: 5, labelX: w * 0.80, id: 'dot-a' }
    ];
    var labelY = h * 0.47;
    var lineStartY = labelY - h * 0.035;
    var anchorY = h * 0.35;

    for (var i = 0; i < anchors.length; i++) {
      var a = anchors[i];
      addPath(a.id, visualSdk.circle(a.x, anchorY, r), a.color, 1);
      addArrow(a.labelX, lineStartY, a.x, anchorY + r + 2, a.color, a.id + '-arrow');
      addLabel(a.labelIdx, a.labelX, labelY, 'center', 'middle', a.color);
    }

    addLabel(6, w / 2, h * 0.60, 'center', 'middle', purple);
    addLabel(7, w / 2, h * 0.71, 'center', 'middle', dark);
    addLabel(8, w / 2, h * 0.83, 'center', 'middle', dark);

    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula-figure',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
